Lemma hull_words : forall d k, 0 <= d -> 1 <= k <= 64 ->
  sh (hull_lo d) = 8 * (sh d / 8) /\
  sh (hull_hi (d + k)) = 8 * (sh (d + k - 1) / 8) + 8 /\
  (sh (d + k - 1) / 8 = sh d / 8 \/ sh (d + k - 1) / 8 = sh d / 8 + 1) /\
  8 * (sh d / 8) <= sh d /\ sh d <= sh (d + k - 1) /\ sh (d + k - 1) < 8 * (sh (d + k - 1) / 8) + 8.
