Lemma rw_cells_CB_length : forall mm A k bs, rw_cells bsegs mm A [CB k bs] -> length bs = k.
Proof. intros mm A k bs [[[H _] _] _]. exact H. Qed.

(* [comment removed for export] *)
Section QRead.
  Variables (mm : word -> option byte) (q1 : Z) (qj : list byte).
  Hypothesis QA : u8arr bsegs mm (8 * q1) qj.
  Lemma q_read : forall x, 8 * q1 <= x < 8 * q1 + Z.of_nat (length qj) ->
    ov_read_bytes bsegs mm (wa x) 1 = Some [nth (Z.to_nat (x - 8 * q1)) qj (b8 0)].
  Proof.
    intros x Hx. eapply (u8arr_read bsegs mm (8 * q1) qj (x - 8 * q1)); [exact QA | | lia | f_equal; lia].
    apply nth_error_nth'. lia.
  Qed.
End QRead.
